     3	import java.math.BigDecimal;
     4	import java.math.RoundingMode;
     5	import java.text.DecimalFormat;
     6	import java.text.DecimalFormatSymbols;
     7	import java.util.Locale;
     8	
     9	public final class Money {
    10	    public static final BigDecimal ZERO = new BigDecimal("0.00");
    11	    private static final BigDecimal HUNDRED = BigDecimal.valueOf(100);
    12	
    13	    private Money() {}
    14	
    15	    public static BigDecimal of(String value) {
    16	        return round(new BigDecimal(value));
    17	    }
    18	
    19	    public static BigDecimal round(BigDecimal value) {
    20	        return value.setScale(2, RoundingMode.HALF_EVEN);
    21	    }
    22	
    23	    public static BigDecimal percent(BigDecimal base, int percent) {
    24	        return round(base.multiply(BigDecimal.valueOf(percent)).divide(HUNDRED));
    25	    }
    26	
    27	    /** Formata como R$ 1.234,56. */
    28	    public static String brl(BigDecimal value) {
    29	        DecimalFormat format = new DecimalFormat("#,##0.00", DecimalFormatSymbols.getInstance(Locale.of("pt", "BR")));
    30	        return "R$ " + format.format(value);
    31	    }
    32	}

