=== ReservationService.java
     1	package marealta;
     2	
     3	import java.math.BigDecimal;
     4	import java.time.LocalDate;
     5	import java.util.ArrayList;
     6	import java.util.List;
     7	
     8	public class ReservationService {
     9	    public record NewReservation(int roomNumber, String guestName, String guestEmail, String guestCpf,
    10	                                 LocalDate checkIn, LocalDate checkOut, int guests, RatePlan plan,
    11	                                 String companyCode) {}
    12	
    13	    private final List<Room> rooms = List.of(
    14	            new Room(101, RoomType.STANDARD),
    15	            new Room(102, RoomType.STANDARD),
    16	            new Room(201, RoomType.DELUXE),
    17	            new Room(202, RoomType.DELUXE),
    18	            new Room(301, RoomType.SUITE));
    19	    private final List<Reservation> reservations = new ArrayList<>();
    20	    private final Outbox outbox;
    21	
    22	    public ReservationService(Outbox outbox) {
    23	        this.outbox = outbox;
    24	    }
    25	
    26	    public List<Room> rooms() { return rooms; }
    27	
    28	    public synchronized List<Reservation> reservations() { return List.copyOf(reservations); }
    29	
    30	    public synchronized Reservation create(NewReservation req) {
    31	        Room room = rooms.stream().filter(r -> r.number() == req.roomNumber()).findFirst()
    32	                .orElseThrow(() -> new ApiException(404, "ROOM_NOT_FOUND", "Quarto " + req.roomNumber() + " não existe"));
    33	
    34	        Stay stay = new Stay(room, req.checkIn(), req.checkOut(), req.companyCode());
    35	        req.plan().validate(stay);
    36	
    37	        if (req.guests() > room.capacity()) {
    38	            throw new ApiException(422, "CAPACITY_EXCEEDED",
    39	                    "O quarto " + room.number() + " comporta até " + room.capacity() + " pessoas");
    40	        }
    41	        boolean taken = reservations.stream().anyMatch(r ->
    42	                r.isActive() && r.room().equals(room) && r.overlaps(req.checkIn(), req.checkOut()));
    43	        if (taken) {
    44	            throw new ApiException(409, "ROOM_UNAVAILABLE", "Quarto já reservado em alguma das noites");
    45	        }
    46	
    47	        BigDecimal nightsTotal = Money.ZERO;
    48	        for (LocalDate night = req.checkIn(); night.isBefore(req.checkOut()); night = night.plusDays(1)) {
    49	            nightsTotal = nightsTotal.add(room.priceOn(night));
    50	        }
    51	        Reservation reservation = new Reservation(reservations.size() + 1, room, req.guestName(), req.guestEmail(),
    52	                req.guestCpf(), req.checkIn(), req.checkOut(), req.guests(), req.plan(),
    53	                req.plan().quote(stay, Money.round(nightsTotal)));
    54	        reservations.add(reservation);
    55	        return reservation;
    56	    }
    57	
    58	    public synchronized Reservation get(int id) {
    59	        if (id < 1 || id > reservations.size()) {
    60	            throw new ApiException(404, "RESERVATION_NOT_FOUND", "Reserva " + id + " não existe");
    61	        }
    62	        return reservations.get(id - 1);
    63	    }
    64	
    65	    public synchronized Reservation confirm(int id) {
    66	        Reservation r = get(id);
    67	        r.confirm();
    68	        String receipt = Receipt.of(r).toText();
    69	        outbox.sendEmail(r.guestEmail(), "Reserva confirmada - Pousada Maré Alta",
    70	                "Olá, " + r.guestName() + "!\n\n"
    71	                        + "Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:\n\n"
    72	                        + receipt + "\n\n"
    73	                        + "A entrada é a partir das 14h, e a saída, até as 12h.\n"
    74	                        + "Até breve!");
    75	        return r;
    76	    }
    77	
    78	    public synchronized Reservation cancel(int id) {
    79	        Reservation r = get(id);
    80	        r.cancel();
    81	        return r;
    82	    }
    83	
    84	    public synchronized Reservation checkIn(int id) {
    85	        Reservation r = get(id);
    86	        r.checkIn();
    87	        return r;
    88	    }
    89	
    90	    public synchronized Receipt checkOut(int id) {
    91	        Reservation r = get(id);
    92	        r.checkOut();
    93	        return Receipt.of(r);
    94	    }
    95	
    96	    public synchronized Receipt document(int id) {
    97	        Reservation r = get(id);
    98	        if (!r.isPaid()) {
    99	            throw ApiException.notAllowed("Segunda via só existe para reserva paga");
   100	        }
   101	        return Receipt.of(r);
   102	    }
   103	}
