     1	package marealta;
     2	
     3	import java.math.BigDecimal;
     4	import java.time.LocalDate;
     5	
     6	import static marealta.ReservationStatus.*;
     7	
     8	public class Reservation {
     9	    private final int id;
    10	    private final Room room;
    11	    private final String guestName;
    12	    private final String guestEmail;
    13	    private final String guestCpf;
    14	    private final LocalDate checkIn;
    15	    private final LocalDate checkOut;
    16	    private final int guests;
    17	    private final RatePlan plan;
    18	    private final int nights;
    19	    private final Quote quote;
    20	
    21	    private ReservationStatus status = PENDING;
    22	    private BigDecimal amountPaid = Money.ZERO;
    23	    private BigDecimal refund;
    24	
    25	    public Reservation(int id, Room room, String guestName, String guestEmail, String guestCpf,
    26	                       LocalDate checkIn, LocalDate checkOut, int guests, RatePlan plan, Quote quote) {
    27	        this.id = id;
    28	        this.room = room;
    29	        this.guestName = guestName;
    30	        this.guestEmail = guestEmail;
    31	        this.guestCpf = guestCpf;
    32	        this.checkIn = checkIn;
    33	        this.checkOut = checkOut;
    34	        this.guests = guests;
    35	        this.plan = plan;
    36	        this.quote = quote;
    37	        this.nights = new Stay(room, checkIn, checkOut, null).nights();
    38	    }
    39	
    40	    public void confirm() {
    41	        require("confirmar", PENDING);
    42	        status = CONFIRMED;
    43	        amountPaid = total();
    44	    }
    45	
    46	    public void checkIn() {
    47	        require("fazer check-in de", CONFIRMED);
    48	        status = CHECKED_IN;
    49	    }
    50	
    51	    public void checkOut() {
    52	        require("fazer check-out de", CHECKED_IN);
    53	        status = CHECKED_OUT;
