    28	    public synchronized List<Reservation> reservations() { return List.copyOf(reservations); }
    29	
    30	    public synchronized Reservation create(NewReservation req) {
    31	        Room room = rooms.stream().filter(r -> r.number() == req.roomNumber()).findFirst()
    32	                .orElseThrow(() -> new ApiException(404, "ROOM_NOT_FOUND", "Quarto " + req.roomNumber() + " não existe"));
    33	
    34	        Stay stay = new Stay(room, req.checkIn(), req.checkOut(), req.companyCode());
    35	        req.plan().validate(stay);
    36	
    37	        if (req.guests() > room.capacity()) {
    38	            throw new ApiException(422, "CAPACITY_EXCEEDED",
    39	                    "O quarto " + room.number() + " comporta até " + room.capacity() + " pessoas");
    40	        }
    41	        boolean taken = reservations.stream().anyMatch(r ->
    42	                r.isActive() && r.room().equals(room) && r.overlaps(req.checkIn(), req.checkOut()));
    43	        if (taken) {
    44	            throw new ApiException(409, "ROOM_UNAVAILABLE", "Quarto já reservado em alguma das noites");
    45	        }
    46	
    47	        BigDecimal nightsTotal = Money.ZERO;
    48	        for (LocalDate night = req.checkIn(); night.isBefore(req.checkOut()); night = night.plusDays(1)) {
    49	            nightsTotal = nightsTotal.add(room.priceOn(night));
    50	        }
    51	        Reservation reservation = new Reservation(reservations.size() + 1, room, req.guestName(), req.guestEmail(),
    52	                req.guestCpf(), req.checkIn(), req.checkOut(), req.guests(), req.plan(),
    53	                req.plan().quote(stay, Money.round(nightsTotal)));
    54	        reservations.add(reservation);
    55	        return reservation;
    56	    }
