     3	import java.math.BigDecimal;
     4	import java.time.LocalDate;
     5	import java.time.YearMonth;
     6	import java.util.Comparator;
     7	import java.util.List;
     8	
     9	public class Reports {
    10	    private final ReservationService service;
    11	
    12	    public Reports(ReservationService service) {
    13	        this.service = service;
    14	    }
    15	
    16	    public String occupancy(LocalDate night) {
    17	        List<Reservation> occupying = service.reservations().stream()
    18	                .filter(r -> r.isPaid() && r.occupiesNight(night))
    19	                .sorted(Comparator.comparingInt((Reservation r) -> r.room().number()))
    20	                .toList();
    21	        StringBuilder csv = new StringBuilder("room,type,reservation,check_in,check_out\n");
    22	        for (Reservation r : occupying) {
    23	            csv.append(r.room().number()).append(',').append(r.room().type()).append(',')
    24	                    .append(r.id()).append(',').append(r.checkInDate()).append(',')
    25	                    .append(r.checkOutDate()).append('\n');
    26	        }
    27	        long occupiedRooms = occupying.stream().map(Reservation::room).distinct().count();
    28	        csv.append("total,").append(occupiedRooms).append('/').append(service.rooms().size()).append('\n');
    29	        return csv.toString();
    30	    }
    31	
    32	    public String revenue(YearMonth month) {
    33	        List<Reservation> kept = service.reservations().stream()
    34	                .filter(r -> YearMonth.from(r.checkInDate()).equals(month) && r.netAmount().signum() > 0)
    35	                .sorted(Comparator.comparing(Reservation::checkInDate).thenComparingInt(Reservation::id))
    36	                .toList();
    37	        StringBuilder csv = new StringBuilder("reservation,room,check_in,check_out,status,amount\n");
    38	        BigDecimal total = Money.ZERO;
    39	        for (Reservation r : kept) {
    40	            csv.append(r.id()).append(',').append(r.room().number()).append(',')
    41	                    .append(r.checkInDate()).append(',').append(r.checkOutDate()).append(',')
    42	                    .append(r.status()).append(',').append(r.netAmount().toPlainString()).append('\n');
    43	            total = total.add(r.netAmount());
    44	        }
    45	        csv.append("total,").append(total.toPlainString()).append('\n');
    46	        return csv.toString();
    47	    }
    48	}
